use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Branches\BranchContextService;use Vendi\Reports\{CustomerStaffReportService,EmployeeReportService};
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();ApiGuard::permission('reports.view');$db=Connection::get();$b=(int)$u['business_id'];$branch=(int)(new BranchContextService($db))->activeBranchId($u);ApiGuard::branch($branch);$f=(string)($_GET['from']??date('Y-m-01'));$t=(string)($_GET['to']??date('Y-m-d'));$type=(string)($_GET['type']??'customers_overview');$r=new CustomerStaffReportService($db);$e=new EmployeeReportService($db);$data=match($type){'customers_overview'=>$r->customers($b,$branch,$f,$t),'customers_history'=>$r->history($b,$branch,$f,$t),'customers_new','customers_series'=>$r->newCustomers($b,$f,$t),'team_activity'=>$r->activity($b,$branch,$f,$t),'team_performance','commissions_overview'=>$e->performance($b,$branch,$f,$t),'commissions_movements'=>$e->commissions($b,$branch,$f,$t),default=>throw new RuntimeException('Reporte no disponible.')};echo json_encode(['ok'=>true,'data'=>$data],JSON_UNESCAPED_UNICODE);}catch(Throwable$e){http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
